MAX_TRAIN_PAIRS_PER_STEP = 256

def load_split(step,split='test'):
    with np.load(ENCODER_ROOT/'windows'/f'{step}.npz') as z:
        x=z[split]
        meta={k:z[f'{split}_{k}'] for k in ('process_id','position_bin','cohort_key')}
    return x,meta

def matched_candidates(meta):
    groups=defaultdict(list)
    for i,(pos,cohort) in enumerate(zip(meta['position_bin'],meta['cohort_key'])):
        groups[(int(pos),str(cohort))].append(i)
    result={}
    for i,(pos,cohort,process) in enumerate(zip(meta['position_bin'],meta['cohort_key'],meta['process_id'])):
        pool=[j for j in groups[(int(pos),str(cohort))] if str(meta['process_id'][j])!=str(process)]
        if pool: result[i]=pool
    return result

def scenarios(step,split='test'):
    x,meta=load_split(step,split); candidates=matched_candidates(meta); indices=list(candidates)
    limit=MAX_TRAIN_PAIRS_PER_STEP if split=='train' else MAX_PAIRS_PER_STEP
    if not indices: raise ValueError(f'{step}: no matched {split} cross-run pairs')
    rng=np.random.default_rng(SEED+sum(map(ord,step))+({'train':10000,'test':20000}[split]))
    if len(indices)>limit: indices=rng.choice(indices,size=limit,replace=False).tolist()
    current=x[indices]; positions=np.asarray(meta['position_bin'])[indices]; references=[]
    for item in indices:
        pool=np.asarray(candidates[item]); selected=rng.choice(pool,size=min(16,len(pool)),replace=False)
        references.append(np.median(x[selected],axis=0))
    return {'real_cross_run':(current,np.asarray(references,dtype=np.float32),positions)}

def selection_metrics(rewards,pred,n):
    rewards=np.asarray(rewards,dtype=float); pred=np.asarray(pred,dtype=int)
    if rewards.ndim!=2 or rewards.shape[1]!=n or len(rewards)!=len(pred) or not len(pred):
        raise ValueError('Nonempty rewards/predictions with matching declared classes required')
    if not np.isfinite(rewards).all() or np.any((pred<0)|(pred>=n)):
        raise ValueError('Invalid reward or prediction')
    # Same argmax proxy target as the existing evaluator. Report ties explicitly.
    target=rewards.argmax(1); present=np.unique(target)
    f1=[]
    for cls in range(n):
        tp=np.sum((target==cls)&(pred==cls)); fp=np.sum((target!=cls)&(pred==cls)); fn=np.sum((target==cls)&(pred!=cls))
        f1.append(2*tp/max(1,2*tp+fp+fn))
    chosen=rewards[np.arange(len(pred)),pred]; oracle=rewards.max(1)
    return {'pairs':len(pred),'reward_argmax_accuracy':float(np.mean(pred==target)),
            'balanced_accuracy':float(np.mean([np.mean(pred[target==cls]==cls) for cls in present])),
            'macro_f1':float(np.mean(f1)),'classes_present':len(present),
            'mean_selected_reward':float(chosen.mean()),'mean_reward_regret':float((oracle-chosen).mean()),
            'largest_prediction_share':max(Counter(pred).values())/len(pred),
            'target_largest_share':max(Counter(target).values())/len(target),
            'reward_tie_share':float(np.mean(np.isclose(rewards,oracle[:,None],rtol=0,atol=1e-5).sum(1)>1))}

def boolean_metrics(rewards,pred):
    rewards=np.asarray(rewards); pred=np.asarray(pred)
    if rewards.shape[1]!=2: raise ValueError('BOOLEAN requires two criteria')
    target=rewards.argmax(1); tp=int(np.sum((target==1)&(pred==1))); fn=int(np.sum((target==1)&(pred==0)))
    fp=int(np.sum((target==0)&(pred==1))); tn=int(np.sum((target==0)&(pred==0)))
    rate=lambda a,b: a/b if b else np.nan
    return {'change_cases':tp+fn,'no_change_cases':tn+fp,'true_positive':tp,'false_negative':fn,
            'false_positive':fp,'true_negative':tn,'change_recall':rate(tp,tp+fn),
            'false_alarm_rate':rate(fp,fp+tn),'change_precision':rate(tp,tp+fp),
            'specificity':rate(tn,tn+fp)}

def fit_constant_baselines(train_rewards):
    train_rewards=np.asarray(train_rewards,dtype=float)
    if train_rewards.ndim!=2 or not len(train_rewards) or not np.isfinite(train_rewards).all():
        raise ValueError('Baselines require nonempty finite TRAIN rewards')
    counts=np.bincount(train_rewards.argmax(1),minlength=train_rewards.shape[1])
    return {'always_first':0,'train_majority':int(counts.argmax()),
            'train_best_constant_reward':int(train_rewards.mean(0).argmax())}

@torch.no_grad()
def collect_train_rewards(step):
    current,reference,positions=scenarios(step,'train')['real_cross_run']; encoder,meta=STEP_ENCODERS[step]
    collected={t:[] for t in CHECKPOINT['criteria']}
    for start in range(0,len(current),BATCH_SIZE):
        a=torch.from_numpy(current[start:start+BATCH_SIZE]).to(DEVICE)
        b=torch.from_numpy(reference[start:start+BATCH_SIZE]).to(DEVICE)
        pos=torch.from_numpy(positions[start:start+BATCH_SIZE]).to(DEVICE)
        state=numeric_state(encoder,a,b)
        contract=grounded_question_contract(a,b,state,pos,step,meta,torch.arange(start,start+len(a),device=DEVICE),'train')
        for t in collected: collected[t].append(contract['rewards'][t].cpu().numpy())
    return {t:np.concatenate(parts) for t,parts in collected.items()}

@torch.no_grad()
def evaluate(step,name,args):
    current,reference,positions=args; encoder,meta=STEP_ENCODERS[step]
    collected={t:{'pred':[],'rewards':[],'confidence':[]} for t in CHECKPOINT['criteria']}; evidence=[]
    for start in range(0,len(current),BATCH_SIZE):
        a=torch.from_numpy(current[start:start+BATCH_SIZE]).to(DEVICE); b=torch.from_numpy(reference[start:start+BATCH_SIZE]).to(DEVICE)
        pos=torch.from_numpy(positions[start:start+BATCH_SIZE]).to(DEVICE); state=numeric_state(encoder,a,b); pc=state.shape[1]//a.shape[2]
        contract=grounded_question_contract(a,b,state,pos,step,meta,torch.arange(start,start+len(a),device=DEVICE),'test')
        descriptions=numeric_token_descriptions(step,meta,pc,len(a))
        for t,item in collected.items():
            criteria=CHECKPOINT['criteria'][t]
            logits,attention=GEVIS_MODEL(state,contract['questions'][t],[t]*len(a),[criteria]*len(a),descriptions)
            prob=torch.stack(logits).softmax(-1)
            item['pred'].append(prob.argmax(-1).cpu().numpy()); item['rewards'].append(contract['rewards'][t].cpu().numpy())
            item['confidence'].extend(prob.max(-1).values.cpu().tolist())
            if t=='CHOICE':
                evidence.extend((attention.argmax(-1)//pc==contract['sensor_ids']).cpu().tolist())
    rows=[]
    for t,item in collected.items():
        pred=np.concatenate(item['pred']); rewards=np.concatenate(item['rewards'])
        EVALUATION_RECORDS.append({'scenario':name,'step':step,'answer_type':t,'pred':pred,'rewards':rewards})
        rows.append({'scenario':name,'step':step,'answer_type':t,**selection_metrics(rewards,pred,len(CHECKPOINT['criteria'][t])),
                     'mean_confidence':float(np.mean(item['confidence'])),'typed_consistency':np.nan})
    return rows,{'step':step,'pairs':len(evidence),'sensor_top1_accuracy':float(np.mean(evidence)) if evidence else np.nan}

def _path_metrics(target,predicted,class_count):
    target=np.asarray(target,dtype=np.int64); predicted=np.asarray(predicted,dtype=np.int64); present=np.unique(target)
    confusion=np.zeros((class_count,class_count),dtype=np.int64); np.add.at(confusion,(target,predicted),1)
    recalls=[]; f1=[]
    for cls in present:
        tp=confusion[cls,cls]; fn=confusion[cls].sum()-tp; fp=confusion[:,cls].sum()-tp
        recalls.append(tp/max(1,tp+fn)); f1.append(2*tp/max(1,2*tp+fp+fn))
    return {'confusion':confusion.tolist(),'questions':len(target),'answer_accuracy':float(np.mean(target==predicted)),'balanced_accuracy_present_classes':float(np.mean(recalls)),'macro_f1_present_classes':float(np.mean(f1)),'classes_present':int(len(present)),'target_largest_share':float(np.bincount(target,minlength=class_count).max()/len(target)),'prediction_largest_share':float(np.bincount(predicted,minlength=class_count).max()/len(predicted))}

@torch.no_grad()
def evaluate_predicted_paths(loaders,split='test'):
    ns=STRUCTURED_NS; model=ns['gevis']; model.eval(); records=[]; quality=[]
    for step,loader in loaders.items():
        encoder,meta=ns['encoders'][step]; encoder.to(ns['DEVICE']).eval(); offset=0
        collected={(kind,path):{'target':[],'predicted':[]} for kind in ns['ANSWER_TYPES'] for path in ('oracle','semantic_only','grounding_only','full_gevis')}
        grounding=[]; semantic={name:[] for name in ('statistic','direction','time_scope')}
        for current,reference,positions in loader:
            current,reference,positions=current.to(ns['DEVICE']),reference.to(ns['DEVICE']),positions.to(ns['DEVICE'])
            state=ns['numeric_state'](encoder,current,reference); patches=state.shape[1]//current.shape[2]; rows=torch.arange(len(current),device=ns['DEVICE'])
            ids=torch.arange(offset,offset+len(current),device=ns['DEVICE']); offset+=len(current)
            contract=ns['grounded_question_contract'](current,reference,state,positions,step,meta,ids,split); descriptions=ns['numeric_token_descriptions'](step,meta,patches,len(current))
            for kind in ns['ANSWER_TYPES']:
                fusion=model(state,contract['questions'][kind],[kind]*len(current),[ns['CRITERIA'][kind]]*len(current),descriptions,return_fusion=True)
                attention=fusion[2].reshape(len(current),current.shape[2],patches); predicted_sensor=attention.sum(-1).argmax(-1)
                text=model._text(contract['questions'][kind],ns['DEVICE']); predicted_statistic=model.semantic_heads['statistic'](text).argmax(-1); predicted_direction=model.semantic_heads['direction'](text).argmax(-1); predicted_scope=model.semantic_heads['time_scope'](text).argmax(-1)
                target_selected=contract['features'][rows,contract['scope_ids'],contract['sensor_ids']]
                target=ns['gevis_fast'].typed_targets(target_selected,contract['statistic_ids'],contract['direction_ids'])[0][kind]
                paths={
                    'oracle':(contract['sensor_ids'],contract['scope_ids'],contract['statistic_ids'],contract['direction_ids']),
                    'semantic_only':(contract['sensor_ids'],predicted_scope,predicted_statistic,predicted_direction),
                    'grounding_only':(predicted_sensor,contract['scope_ids'],contract['statistic_ids'],contract['direction_ids']),
                    'full_gevis':(predicted_sensor,predicted_scope,predicted_statistic,predicted_direction),
                }
                for path,(sensor,scope,statistic,direction) in paths.items():
                    selected=contract['features'][rows,scope,sensor]
                    probability,_=ns['gevis_fast'].structured_answer_probabilities(selected,statistic,direction,temperature=ns['CONFIG'].reward_temperature)
                    item=collected[(kind,path)]; item['target']+=target.cpu().tolist(); item['predicted']+=probability[kind].argmax(-1).cpu().tolist()
                grounding+=predicted_sensor.eq(contract['sensor_ids']).cpu().tolist()
                # CHOICE/ORDINAL questions do not declare a statistic/direction.
                if kind=='BOOLEAN':
                    semantic['statistic']+=predicted_statistic.eq(contract['statistic_ids']).cpu().tolist()
                    semantic['direction']+=predicted_direction.eq(contract['direction_ids']).cpu().tolist()
                semantic['time_scope']+=predicted_scope.eq(contract['scope_ids']).cpu().tolist()
        encoder.cpu()
        for (kind,path),item in collected.items(): records.append({'decision_policy':'LEGACY_fixed_1.0','split':split,'step':step,'answer_type':kind,'execution_path':path,**_path_metrics(item['target'],item['predicted'],len(ns['CRITERIA'][kind]))})
        quality.append({'split':split,'step':step,'sensor_grounding_accuracy':float(np.mean(grounding)),'statistic_semantic_accuracy':float(np.mean(semantic['statistic'])),'direction_semantic_accuracy':float(np.mean(semantic['direction'])),'time_scope_semantic_accuracy':float(np.mean(semantic['time_scope'])),'statistic_direction_scored_types':'BOOLEAN only'})
    return pd.DataFrame(records),pd.DataFrame(quality)

