elif globals().get('EXPERIMENT_MODE','typed')=='typed':
    # Internal arrays stay in memory: no per-case display, logging or export.
    EVALUATION_RECORDS=[]; rows=[]; evidence=[]
    for step in STEP_ENCODERS:
        for name,args in scenarios(step).items():
