if globals().get('EXPERIMENT_MODE','typed')=='typed':
    # Every baseline selection uses TRAIN only; all methods share the identical held-out questions.
    TRAIN_BASELINES={}
    for step in STEP_ENCODERS:
        print({'phase':'train_baseline','step':step},flush=True)
        train_rewards=collect_train_rewards(step)
        TRAIN_BASELINES[step]={t:fit_constant_baselines(values) for t,values in train_rewards.items()}
        del train_rewards

    comparison_rows=[]; pooled=defaultdict(list)
    for record in EVALUATION_RECORDS:
        t=record['answer_type']; step=record['step']; rewards=record['rewards']; n=len(CHECKPOINT['criteria'][t])
        predictions={'GEVIS_LJR':record['pred']}
        predictions.update({method:np.full(len(rewards),cls,dtype=int) for method,cls in TRAIN_BASELINES[step][t].items()})
        for method,pred in predictions.items():
            row={'scenario':record['scenario'],'step':step,'answer_type':t,'method':method,
                 'constant_answer':None if method=='GEVIS_LJR' else CHECKPOINT['criteria'][t][int(pred[0])],
                 **selection_metrics(rewards,pred,n)}
            if t=='BOOLEAN': row.update(boolean_metrics(rewards,pred))
            comparison_rows.append(row); pooled[(record['scenario'],t,method)].append((rewards,pred))

    comparison_by_step=pd.DataFrame(comparison_rows)
    summary_rows=[]
    for (scenario,t,method),parts in pooled.items():
        rewards=np.concatenate([part[0] for part in parts]); pred=np.concatenate([part[1] for part in parts])
        row={'scenario':scenario,'answer_type':t,'method':method,**selection_metrics(rewards,pred,len(CHECKPOINT['criteria'][t]))}
        if t=='BOOLEAN': row.update(boolean_metrics(rewards,pred))
        summary_rows.append(row)
    comparison_summary=pd.DataFrame(summary_rows)
    base=comparison_summary.loc[comparison_summary.method.eq('train_majority'),['scenario','answer_type','reward_argmax_accuracy','balanced_accuracy','mean_reward_regret']].rename(columns={'reward_argmax_accuracy':'baseline_accuracy','balanced_accuracy':'baseline_balanced_accuracy','mean_reward_regret':'baseline_regret'})
    comparison_summary=comparison_summary.merge(base,on=['scenario','answer_type'],validate='many_to_one')
    comparison_summary['accuracy_gain_vs_majority']=comparison_summary.reward_argmax_accuracy-comparison_summary.baseline_accuracy
    comparison_summary['balanced_accuracy_gain_vs_majority']=comparison_summary.balanced_accuracy-comparison_summary.baseline_balanced_accuracy
    comparison_summary['regret_reduction_vs_majority']=comparison_summary.baseline_regret-comparison_summary.mean_reward_regret

    display(comparison_summary[['scenario','answer_type','method','pairs','reward_argmax_accuracy','balanced_accuracy','macro_f1','target_largest_share','accuracy_gain_vs_majority','balanced_accuracy_gain_vs_majority','regret_reduction_vs_majority']].style.hide(axis='index'))
    display(comparison_by_step.style.hide(axis='index'))
    boolean_diagnostics=comparison_summary.loc[comparison_summary.answer_type.eq('BOOLEAN'),['scenario','method','change_cases','no_change_cases','true_positive','false_negative','false_positive','true_negative','change_recall','false_alarm_rate','change_precision','specificity']]
    display(boolean_diagnostics.style.hide(axis='index'))
    print({'target':'question-specific numeric proxy condition, not verified equipment fault',
           'missing_positive_or_negative':'NaN rates indicate absent cases; no detection claim is possible',
           'evaluation_mode':'raw answer scorer before runtime semantic/confidence abstention',
           'LJR_attribution':'baseline comparison does not isolate LJR; supervised-only ablation is separate'})

